Map<String, String> _selectEnglishMechanisms(String? countryCode) {
  if (countryCode == null) return _enMechanisms;
  final code = countryCode.trim().toUpperCase();
  const easternCodes = {'VN', 'CN', 'JP', 'KR', 'TW', 'SG', 'HK', 'MO'};
  const vedicCodes = {'IN', 'NP', 'LK', 'BD', 'PK', 'BT'};
